changeSet.sql:
CREATE TABLE payouts ( id uuid NOT NULL PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations (id), branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
transaction_id uuid NOT NULL REFERENCES transactions (id), settlement_account_id uuid NOT NULL REFERENCES settlement_accounts (id), recipient_code varchar(64) NOT NULL, amount numeric(19,2) NOT NULL, currency varchar(3) NOT NULL, amount_kobo bigint NOT NULL, reference varchar(64) NOT NULL UNIQUE, transfer_code varchar(64), status varchar(16) NOT NULL, gateway_message varchar(500), initiated_by uuid NOT NULL REFERENCES users (id), finalized_by uuid REFERENCES users (id), cancelled_by uuid REFERENCES users (id), transferred_at timestamp(6) with time zone,
CONSTRAINT chk_payouts_status CHECK (status IN ('SENDING', 'AWAITING_OTP', 'PENDING', 'SUCCESS', 'FAILED', 'REVERSED', 'CANCELLED')), CONSTRAINT chk_payouts_amount_positive CHECK (amount > 0 AND amount_kobo > 0), CONSTRAINT chk_payouts_currency CHECK (currency = 'NGN') ); CREATE UNIQUE INDEX uq_payouts_one_live_per_sale ON payouts (transaction_id) WHERE status IN ('SENDING', 'AWAITING_OTP', 'PENDING', 'SUCCESS') AND deleted = false; CREATE INDEX idx_payouts_status ON payouts (status, created_at); CREATE INDEX idx_payouts_transaction ON payouts (transaction_id, created_at DESC);
ALTER TABLE payouts ENABLE ROW LEVEL SECURITY; ALTER TABLE payouts FORCE ROW LEVEL SECURITY; CREATE POLICY payouts_platform ON payouts FOR ALL USING (current_setting('landvault.platform_scope', true) = 'on') WITH CHECK (current_setting('landvault.platform_scope', true) = 'on'); CREATE POLICY payouts_tenant_read ON payouts FOR SELECT USING ( current_setting('landvault.tenant_id', true) IS NOT NULL AND current_setting('landvault.tenant_id', true) != '' AND tenant_id::text = current_setting('landvault.tenant_id', true) ); REVOKE DELETE, TRUNCATE ON payouts FROM ${appDbUsername};
COMMENT ON TABLE payouts IS 'Payout attempts to a company for a verified sale. At most one live attempt per sale (unique index). Written before Paystack is asked. Never deleted. See AGENTS.md, "Payments".';
